class Widget {};

// Factory function safely returning a shared resource
std::shared_ptr<Widget> createWidget() {
    // Safest way: Use make_shared (covered in Item 21)
    return std::make_shared<Widget>();
}

// Alternative for custom deleters: pass 'new' directly
std::shared_ptr<Widget> createWidgetWithDeleter() {
    return std::shared_ptr<Widget>(new Widget, [](Widget* w){ delete w; });
}

void run_example() {
    // Get the first owning pointer
    auto spw1 = createWidget();

    // Propagate ownership correctly by copying the existing shared_ptr
    std::shared_ptr<Widget> spw2 = spw1; // Copy construction, increments ref count
    auto spw3 = spw1; // Another copy, increments ref count again

    // All three pointers share the same control block. The Widget is deleted
    // only when spw1, spw2, and spw3 have all gone out of scope.
    // std::cout << spw1.use_count(); // Would print 3
}
